/// The resource returned by [`Client::fetch`]. The variant follows the
/// platform and resource the URL represents.
#[derive(Clone, Debug, PartialEq)]
#[non_exhaustive]
pub enum FetchResource {
    /// A instagram profile.
    InstagramProfile(Box<InstagramProfile>),
    /// A instagram post.
    InstagramPost(Box<InstagramPost>),
    /// A instagram story.
    InstagramStory(Box<InstagramStory>),
    /// A instagram highlight.
    InstagramHighlight(Box<InstagramHighlight>),
    /// A tiktok profile.
    TikTokProfile(Box<TikTokProfile>),
    /// A tiktok post.
    TikTokPost(Box<TikTokPost>),
    /// A twitter profile.
    TwitterProfile(Box<TwitterProfile>),
    /// A twitter post.
    TwitterPost(Box<TwitterPost>),
    /// A reddit profile.
    RedditProfile(Box<RedditProfile>),
    /// A reddit post.
    RedditPost(Box<RedditPost>),
    /// A reddit subreddit.
    RedditSubreddit(Box<RedditSubreddit>),
}

impl FetchResource {
    pub(crate) fn decode(
        platform: &str,
        resource: &str,
        data: serde_json::Value,
    ) -> Result<Option<Self>, serde_json::Error> {
        match (platform, resource) {
            ("instagram", "profile") => serde_json::from_value(data)
                .map(|value| Some(Self::InstagramProfile(Box::new(value)))),
            ("instagram", "post") => {
                serde_json::from_value(data).map(|value| Some(Self::InstagramPost(Box::new(value))))
            }
            ("instagram", "story") => serde_json::from_value(data)
                .map(|value| Some(Self::InstagramStory(Box::new(value)))),
            ("instagram", "highlight") => serde_json::from_value(data)
                .map(|value| Some(Self::InstagramHighlight(Box::new(value)))),
            ("tiktok", "profile") => {
                serde_json::from_value(data).map(|value| Some(Self::TikTokProfile(Box::new(value))))
            }
            ("tiktok", "post") => {
                serde_json::from_value(data).map(|value| Some(Self::TikTokPost(Box::new(value))))
            }
            ("twitter", "profile") => serde_json::from_value(data)
                .map(|value| Some(Self::TwitterProfile(Box::new(value)))),
            ("twitter", "post") => {
                serde_json::from_value(data).map(|value| Some(Self::TwitterPost(Box::new(value))))
            }
            ("reddit", "profile") => {
                serde_json::from_value(data).map(|value| Some(Self::RedditProfile(Box::new(value))))
            }
            ("reddit", "post") => {
                serde_json::from_value(data).map(|value| Some(Self::RedditPost(Box::new(value))))
            }
            ("reddit", "subreddit") => serde_json::from_value(data)
                .map(|value| Some(Self::RedditSubreddit(Box::new(value)))),
            _ => Ok(None),
        }
    }
}

/// Typed result of [`Client::fetch`].
pub type FetchResponse = Response<FetchResource>;

